p='src/content/vunjo.ts'; s=open(p).read()
missing=[]
def rep(m):
    en=m.group(1)
    sw=SW.get(en)
    if not sw: missing.append(en); return m.group(0)
    return f'{{ en: "{en}", sw: "{sw}",'
s2=re.sub(r'\{ en: "([^"]+)",', rep, s)
